package com.productionhouse.crm.mediahouse.postproduction.service;
import com.productionhouse.crm.auth.api.ApiException;import com.productionhouse.crm.auth.entity.CrmUser;import com.productionhouse.crm.auth.repository.UserRepository;import com.productionhouse.crm.mediahouse.media.entity.MediaAsset;import com.productionhouse.crm.mediahouse.media.repository.MediaAssetRepository;import com.productionhouse.crm.mediahouse.postproduction.dto.*;import com.productionhouse.crm.mediahouse.postproduction.entity.PostProductionTask;import com.productionhouse.crm.mediahouse.postproduction.repository.PostProductionTaskRepository;import com.productionhouse.crm.task5.util.Task5Paging;import org.springframework.data.domain.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.LocalDate;import java.util.*;
@Service public class PostProductionTaskService{
private static final Set<String> STATUSES=Set.of("NOT_STARTED","IN_PROGRESS","IN_REVIEW","COMPLETED","ON_HOLD");
private final PostProductionTaskRepository repo;private final MediaAssetRepository mediaRepo;private final UserRepository users;public PostProductionTaskService(PostProductionTaskRepository repo,MediaAssetRepository mediaRepo,UserRepository users){this.repo=repo;this.mediaRepo=mediaRepo;this.users=users;}
@Transactional(readOnly=true) public Page<PostProductionTaskResponse> list(String q,String status,String projectRef,Long assigneeId,LocalDate dueBefore,LocalDate dueAfter,int page,int size,String sort,String direction){String field=Set.of("name","status","createdAt","updatedAt","dueAt","startedAt").contains(sort)?sort:"createdAt";Sort order=Sort.by("asc".equalsIgnoreCase(direction)?Sort.Direction.ASC:Sort.Direction.DESC,field);return Task5Paging.page(repo.findAll(order).stream().filter(e->blank(q)||contains(e.getName(),q)||contains(e.getDescription(),q)).filter(e->blank(status)||status.equalsIgnoreCase(e.getStatus())).filter(e->blank(projectRef)||projectRef.equals(e.getProjectRef())).filter(e->assigneeId==null||e.getAssignedTo()!=null&&assigneeId.equals(e.getAssignedTo().getId())).filter(e->dueBefore==null||e.getDueAt()!=null&&!e.getDueAt().isAfter(dueBefore)).filter(e->dueAfter==null||e.getDueAt()!=null&&!e.getDueAt().isBefore(dueAfter)).map(this::response).toList(),page,size);}
@Transactional(readOnly=true) public PostProductionTaskResponse get(Long id){return response(find(id));}
@Transactional public PostProductionTaskResponse create(PostProductionTaskRequest r){return response(save(new PostProductionTask(),r));}
@Transactional public PostProductionTaskResponse update(Long id,PostProductionTaskRequest r){return response(save(find(id),r));}
@Transactional public void delete(Long id){repo.delete(find(id));}
private PostProductionTask find(Long id){return repo.findById(id).orElseThrow(()->ApiException.notFound("Post-production task not found."));}
private PostProductionTask save(PostProductionTask e,PostProductionTaskRequest r){String status=r.status().trim().toUpperCase(Locale.ROOT);if(!STATUSES.contains(status))throw ApiException.badRequest("Unsupported post-production status.");if(e.getId()!=null&&!e.getStatus().equals(status)){boolean ok=switch(e.getStatus()){case "NOT_STARTED"->Set.of("IN_PROGRESS","ON_HOLD").contains(status);case "IN_PROGRESS"->Set.of("IN_REVIEW","ON_HOLD").contains(status);case "IN_REVIEW"->Set.of("IN_PROGRESS","COMPLETED","ON_HOLD").contains(status);case "ON_HOLD"->Set.of("NOT_STARTED","IN_PROGRESS").contains(status);default->false;};if(!ok)throw ApiException.badRequest("Invalid post-production status transition.");}
if(r.startedAt()!=null&&r.dueAt()!=null&&r.dueAt().isBefore(r.startedAt()))throw ApiException.badRequest("dueAt must be on or after startedAt.");if("COMPLETED".equals(status)&&r.completedAt()==null)throw ApiException.badRequest("completedAt is required for completed tasks.");if(!"COMPLETED".equals(status)&&r.completedAt()!=null)throw ApiException.badRequest("completedAt is only valid for completed tasks.");
MediaAsset media=r.mediaId()==null?null:mediaRepo.findById(r.mediaId()).orElseThrow(()->ApiException.badRequest("Referenced media asset does not exist."));CrmUser assignee=r.assigneeId()==null?null:users.findById(r.assigneeId()).orElseThrow(()->ApiException.badRequest("Referenced assignee does not exist."));
e.setName(r.name().trim());e.setDescription(clean(r.description()));e.setProjectRef(clean(r.projectRef()));e.setMediaAsset(media);e.setAssignedTo(assignee);e.setStatus(status);e.setPriority(clean(r.priority()));e.setStartedAt(r.startedAt());e.setDueAt(r.dueAt());e.setCompletedAt(r.completedAt());e.setNotes(clean(r.notes()));e.setActive(r.active()==null||r.active());return repo.save(e);}
private PostProductionTaskResponse response(PostProductionTask e){return new PostProductionTaskResponse(e.getId(),e.getName(),e.getDescription(),e.getProjectRef(),e.getMediaAsset()==null?null:e.getMediaAsset().getId(),e.getAssignedTo()==null?null:e.getAssignedTo().getId(),e.getAssignedTo()==null?null:e.getAssignedTo().getName(),e.getStatus(),e.getPriority(),e.getStartedAt(),e.getDueAt(),e.getCompletedAt(),e.getNotes(),e.isActive(),e.getCreatedAt(),e.getUpdatedAt());}
private boolean blank(String x){return x==null||x.isBlank();}private boolean contains(String x,String q){return x!=null&&x.toLowerCase(Locale.ROOT).contains(q.trim().toLowerCase(Locale.ROOT));}private String clean(String x){return x==null||x.isBlank()?null:x.trim();}}

